185	  public DataNodeVolumeMetrics(final MetricsSystem metricsSystem,
186	      final String volumeName, final int[] intervals) {
187	    this.ms = metricsSystem;
188	    this.name = volumeName;
189	    final int len = intervals.length;
190	    metadataOperationLatencyQuantiles = new MutableQuantiles[len];
191	    dataFileIoLatencyQuantiles = new MutableQuantiles[len];
192	    flushIoLatencyQuantiles = new MutableQuantiles[len];
193	    syncIoLatencyQuantiles = new MutableQuantiles[len];
194	    readIoLatencyQuantiles = new MutableQuantiles[len];
195	    writeIoLatencyQuantiles = new MutableQuantiles[len];
196	    for (int i = 0; i < len; i++) {
197	      int interval = intervals[i];
198	      metadataOperationLatencyQuantiles[i] = registry.newQuantiles(
199	          "metadataOperationLatency" + interval + "s",
200	          "Meatadata Operation Latency in ms", "ops", "latency", interval);
201	      dataFileIoLatencyQuantiles[i] = registry.newQuantiles(
202	          "dataFileIoLatency" + interval + "s",
