210	      readIoLatencyQuantiles[i] = registry.newQuantiles(
211	          "readIoLatency" + interval + "s",
212	          "Data read Io Latency in ms", "ops", "latency", interval);
213	      writeIoLatencyQuantiles[i] = registry.newQuantiles(
214	          "writeIoLatency" + interval + "s",
